(function(){"use strict";app.factory("cuentaPorPagarService",function(t){const i=t.get("mainService"),o="Contabilidad/CuentaPorPagar/",e={get:function(t){let e={...t,tipo:"tipo"in t?t.tipo:1};return i.getData("get",`${o}?json=${JSON.stringify(e)}`,null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let i=JSON.parse(t.payload)||[];if(1===e.tipo)return i[0];if(2===e.tipo)return{cuotas:i[0]};if(4===e.tipo&&console.log(i),5===e.tipo)return{tiemposCredito:i[0]}}})}};return e})})(window.angular);